            return 1 << 29
        if index == n:
            return 1 << 29
        if memo[index][sum] != -1:
            return memo[index][sum]
        res = 1 << 28
        for i in range(2, 6):
            res = min(res, (1 if i == 2 else 0) + dp(index + 1, sum + i))
        memo[index][sum] = res
